const rawRequest = $json.body ?? $json;
let request = rawRequest;
const errors = [];
if (typeof rawRequest === 'string') {
  try { request = JSON.parse(rawRequest); } catch { errors.push('Expected a JSON object.'); }
}
const optionalText = (value) => typeof value === 'string' ? value.trim() || null : null;
if (!request || typeof request !== 'object' || Array.isArray(request)) errors.push('Expected a JSON object.');
const fullName = optionalText(request?.full_name);
const email = optionalText(request?.email);
const phone = optionalText(request?.phone);
const message = optionalText(request?.message);
if (!fullName) errors.push('Full name is required.');
if (fullName && fullName.length > 160) errors.push('Full name is too long.');
if (!email && !phone) errors.push('An email address or phone number is required.');
if (email && (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email) || email.length > 254)) errors.push('Enter a valid email address.');
if (phone && (phone.length > 50 || !/^[0-9+().\-\s]{7,50}$/.test(phone))) errors.push('Enter a valid phone number.');
if (!message) errors.push('Message is required.');
if (message && message.length > 5000) errors.push('Message is too long.');
const uuid = /^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i;
if (!uuid.test(request?.submission_id || '')) errors.push('Submission identifier is invalid.');
if (!uuid.test(request?.correlation_id || '')) errors.push('Correlation identifier is invalid.');
if (Number.isNaN(Date.parse(request?.received_at || ''))) errors.push('Received timestamp is invalid.');
return [{ json: { input_valid: errors.length === 0, errors, request } }];

const request = $json.request;
const trim = (value) => typeof value === 'string' ? value.trim() || null : null;
return [{ json: {
  lead: {
    submission_id: request.submission_id,
    correlation_id: request.correlation_id,
    received_at: request.received_at,
    full_name: trim(request.full_name),
    email: trim(request.email)?.toLowerCase() ?? null,
    phone: trim(request.phone),
    original_message: trim(request.message)
  }
} }];

const lead = $('Normalize Contact Data').first().json.lead;
const result = $json;
const allowedServices = new Set(['furnace_service','air_conditioning_service','plumbing_service','electrical_service','general_home_service','unknown']);
const allowedUrgency = new Set(['low','medium','high','urgent']);
let enrichment = null;
let aiStatus = 'fallback_unavailable';
let diagnostic = 'NVIDIA NIM did not return a usable response.';
try {
  const content = result.choices?.[0]?.message?.content;
  const parsed = typeof content === 'string' ? JSON.parse(content) : null;
  const exactKeys = ['service_type', 'location', 'preferred_time', 'urgency', 'summary'];
  if (!parsed || typeof parsed !== 'object' || Object.keys(parsed).some((key) => !exactKeys.includes(key))) throw new Error('Unexpected response shape');
  if (!allowedServices.has(parsed.service_type)) throw new Error('Unsupported service type');
  if (!allowedUrgency.has(parsed.urgency)) throw new Error('Unsupported urgency');
  for (const field of ['location', 'preferred_time']) {
    if (parsed[field] !== null && (typeof parsed[field] !== 'string' || parsed[field].trim().length > 160)) throw new Error('Invalid optional text');
  }
  if (typeof parsed.summary !== 'string' || !parsed.summary.trim() || parsed.summary.length > 600) throw new Error('Invalid summary');
  enrichment = {
    service_type: parsed.service_type,
    location: parsed.location?.trim() || null,
    preferred_time: parsed.preferred_time?.trim() || null,
    urgency: parsed.urgency,
    summary: parsed.summary.trim()
  };
  aiStatus = 'enriched';
  diagnostic = null;
} catch (error) {
  aiStatus = result.error ? 'fallback_unavailable' : 'fallback_invalid';
  diagnostic = aiStatus === 'fallback_invalid' ? 'NVIDIA NIM output failed application schema validation.' : diagnostic;
}
return [{ json: {
  crmPayload: { ...lead, enrichment, ai_status: aiStatus, needs_review: aiStatus !== 'enriched', enrichment_diagnostic: diagnostic }
} }];

if ($json.error) {
  return [{ json: { status_code: 502, response_body: { message: 'We could not process your enquiry. Please try again.' } } }];
}
const crm = $json;
return [{ json: {
  status_code: 201,
  response_body: {
    state: 'accepted',
    submission_id: crm.submission_id,
    correlation_id: crm.correlation_id,
    crm_lead_id: crm.crm_lead_id,
    ai_status: crm.ai_status
  }
} }];

return [{ json: {
  status_code: 422,
  response_body: { message: 'Please correct the highlighted enquiry details.', errors: $json.errors }
} }];
